import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.DSoq407f.js";const c=JSON.parse('{"title":"产品介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1786505997000}'),i={name:"guide/introduction.md"};function l(n,t,s,d,g,h){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="产品介绍" tabindex="-1">产品介绍 <a class="header-anchor" href="#产品介绍" aria-label="Permalink to &quot;产品介绍&quot;">​</a></h1><blockquote><p><strong>你会了解到</strong>：小依 QQ V3 是什么、解决什么问题、适合谁用。</p></blockquote><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>小依 QQ V3（以下简称 <strong>V3</strong>）是一个<strong>多租户的 QQ 机器人 SaaS 管理平台</strong>。</p><p>简单说：你部署一套 V3，就能同时为<strong>很多个客户</strong>各自提供独立的 QQ 机器人服务——每个客户有自己的机器人、自己的插件、自己的订阅和数据，彼此完全隔离，而你用一个统一的后台管理所有人。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>如果你做过 QQ 机器人，大概率踩过这些坑：</p><ul><li><strong>一人一套代码</strong>：给每个客户部署一次、升级一次、出问题排查一次，运维成本随客户数线性增长。</li><li><strong>插件无法复用</strong>：A 客户要签到、B 客户要积分商城，功能各写一遍，没法沉淀成生态。</li><li><strong>没法商业化</strong>：没有订阅、计费、卡密，机器人做得再好也难变现。</li><li><strong>多平台割裂</strong>：QQ 官方、Telegram、Discord 各一套逻辑，换个平台要重写。</li></ul><p>V3 用一套架构解决上面全部问题：</p><table tabindex="0"><thead><tr><th>痛点</th><th>V3 的解法</th></tr></thead><tbody><tr><td>一人一套代码</td><td>多租户：一套系统服务所有客户，数据天然隔离</td></tr><tr><td>插件无法复用</td><td>插件市场：开发者写一次，所有客户、所有平台通用</td></tr><tr><td>没法商业化</td><td>订阅计费：套餐、卡密、余额、分成，开箱即用</td></tr><tr><td>多平台割裂</td><td>XUBP 协议：一套接口，九大平台通用运行</td></tr></tbody></table><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li><strong>平台运营方</strong>：想做一个&quot;卖机器人服务&quot;的生意，需要多租户 + 计费 + 后台管理。</li><li><strong>插件开发者</strong>：会写点 Python，想把自己的机器人功能做成插件卖给平台上的客户、赚取分成。</li><li><strong>企业 / 团队</strong>：内部需要管理多个 QQ 机器人，希望统一管控、权限分明、有审计。</li></ul><h2 id="核心能力一览" tabindex="-1">核心能力一览 <a class="header-anchor" href="#核心能力一览" aria-label="Permalink to &quot;核心能力一览&quot;">​</a></h2><ul><li>🤖 <strong>九大平台适配器</strong>：QQ 官方、OneBot、Telegram、Discord、KOOK、飞书、钉钉、微信公众号、企业微信</li><li>🧩 <strong>插件市场</strong>：上传、定价、上架、收益分成、版本管理</li><li>💳 <strong>订阅与计费</strong>：月/年/永久套餐、卡密兑换、余额充值、彩虹易支付</li><li>🏢 <strong>多租户隔离</strong>：机器人、插件数据、订阅按客户隔离</li><li>🛡️ <strong>RBAC 三级权限</strong>：管理后台 / 用户控制台 / 开发者中心，细粒度控权 + 全操作审计</li><li>🔄 <strong>在线更新</strong>：后台一键升级，增量更新 + 自动重启</li><li>🔌 <strong>Open API</strong>：对外提供 API Key，方便二次集成</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想了解设计思路 → <a href="./features">核心特性</a> · <a href="./architecture">系统架构</a></li><li>想自己部署一套 → <a href="./../deploy/requirements">环境要求</a></li><li>想开发插件 → <a href="./../plugin-dev/getting-started">插件开发快速开始</a></li><li>想理解插件协议 → <a href="./../xubp/overview">XUBP 协议概览</a></li></ul>',16)])])}const p=r(i,[["render",l]]);export{c as __pageData,p as default};
